ime.root_EXTREME_JUMPBOOST_THRESHOLD=50; Runtime.root_JUMPBOOST_SUSTAINED_TIME=0.15; Runtime.root_MAX_VELOCITY_CHANGE=150\nRuntime.root_VELOCITY_SMOOTHING=0.2; Runtime.root_MAX_HORIZONTAL_VELOCITY=80; Runtime.root_ERRATIC_MOVEMENT_THRESHOLD=3\nRuntime.root_SERVER_TICKRATE=1/60; Runtime.root_PING_SAMPLE_SIZE=10; Runtime.root_MIN_PING_COMPENSATION=0.03; Runtime.root_MAX_PING_COMPENSATION=0.25\nRuntime.root_ACCELERATION_PREDICTION_WEIGHT=0.3; Runtime.root_DIRECTION_CHANGE_DETECTION_TIME=0.12; Runtime.root_QUICK_DIRECTION_CHANGE_MULTIPLIER=1.5\nRuntime.root_GRAVITY=196.2; Runtime.root_AIR_CONTROL_FACTOR=0.8; Runtime.root_AERIAL_VELOCITY_DECAY=0.95; Runtime.root_AERIAL_DIRECTION_CHANGE_WEIGHT=0.6\nRuntime.root_MIN_AIRBORNE_TIME=0.08; Runtime.root_AERIAL_SMOOTHING=0.15; Runtime.root_HIGH_JUMP_THRESHOLD=20; Runtime.root_FALLING_SPEED_THRESHOLD=-15\nRuntime.root_GRAVITY_PREDICTION_WEIGHT=1.0; Runtime.root_MULTI_JUMP_DETECTION_WINDOW=0.2; Runtime.root_UPWARD_VELOCITY_RESET_THRESHOLD=10\nRuntime.root_VERTICAL_POSITION_LEAD=2.5; Runtime.root_FALLING_VERTICAL_LEAD=3.5\nRuntime.root_SPHERE_SMOOTH_SPEED=15\nRuntime.root_StatsService=game:GetService(\"Stats\")\nRuntime.root_predictionSphere=nil; Runtime.root_targetPlayer=nil; Runtime.root_lastTargetPos=nil; Runtime.root_targetVelocity=Vector3.new(0,0,0)\nRuntime.root_smoothedVelocity=Vector3.new(0,0,0); Runtime.root_velocityHistory={}; Runtime.root_MAX_HISTORY=8; Runtime.root_airborneTime=0\nRuntime.root_lastActivationTime=0; Runtime.root_highYVelocityTime=0; Runtime.root_pingHistory={}; Runtime.root_currentPing=0.1\nRuntime.root_accelerationHistory={}; Runtime.root_MAX_ACCEL_HISTORY=4\nRuntime.root_lastDirectionChangeTime=0; Runtime.root_previousDirection=nil; Runtime.root_wasAirborne=false\nRuntime.root_aerialVelocityHistory={}; Runtime.root_MAX_AERIAL_HISTORY=6; Runtime.root_aerialSmoothVelocity=Vector3.new(0,0,0)\nRuntime.root_lastYVelocity=0; Runtime.root_peakHeight=0; Runtime.root_groundHeight=0\nRuntime.root_lastJumpTime=0;