a in ipairs(Runtime.root_accelerationHistory) do sum=sum+a end; return sum/#Runtime.root_accelerationHistory end\nfunction Runtime.root_getAverageAerialVelocity() if #Runtime.root_aerialVelocityHistory==0 then return Vector3.new(0,0,0) end; local sum=Vector3.new(0,0,0); for _,vel in ipairs(Runtime.root_aerialVelocityHistory) do sum=sum+Vector3.new(vel.X,0,vel.Z) end; return sum/#Runtime.root_aerialVelocityHistory end\nfunction Runtime.root_getAverageVerticalVelocity() if #Runtime.root_verticalVelocityHistory==0 then return 0 end; local sum=0; for _,y in ipairs(Runtime.root_verticalVelocityHistory) do sum=sum+y end; return sum/#Runtime.root_verticalVelocityHistory end\nfunction Runtime.root_detectMultiJump(currentYVel,wasRising) local t=tick(); if Runtime.root_lastYVelocity<-5 and currentYVel>Runtime.root_UPWARD_VELOCITY_RESET_THRESHOLD then if t-Runtime.root_lastJumpTime<Runtime.root_MULTI_JUMP_DETECTION_WINDOW then return true end; Runtime.root_lastJumpTime=t; return true end; return false end\nfunction Runtime.root_isFallingFromHeight(currentPos,yVel) return (currentPos.Y-Runtime.root_groundHeight>Runtime.root_HIGH_JUMP_THRESHOLD) and yVel<Runtime.root_FALLING_SPEED_THRESHOLD end\nfunction Runtime.root_isAerialStrafing() if #Runtime.root_aerialVelocityHistory<3 then return false end; local dc=0; for i=2,#Runtime.root_aerialVelocityHistory do local v1=Vector3.new(Runtime.root_aerialVelocityHistory[i-1].X,0,Runtime.root_aerialVelocityHistory[i-1].Z); local v2=Vector3.new(Runtime.root_aerialVelocityHistory[i].X,0,Runtime.root_aerialVelocityHistory[i].Z); if v1.Magnitude>3 and v2.Magnitude>3 then if v1.Unit:Dot(v2.Unit)<0.7 then dc=dc+1 end end end; return dc>=2 end\nfunction Runtime.root_detectDirectionChange(currentVel) local horizontal=Vector3.new(currentVel.X,0,currentVel.Z); if horizontal.Magnitude<5 then return false end; if Runtime.root_previousDirection then local dot=Runtime.root_previousDirection:Dot(horizontal.Unit); if dot<0.5 then local t=tick(); if t-Run